<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($quote['quote_number']) ?> · <?= e($siteName) ?></title><style>body{margin:0;background:#07111f;color:#e8f0fa;font:16px/1.55 system-ui,sans-serif}.wrap{max-width:860px;margin:auto;padding:48px 20px}.quote{background:#101d2f;border:1px solid #2a405c;border-radius:24px;box-shadow:0 28px 80px #0008;overflow:hidden}.head,.body{padding:28px}.head{background:linear-gradient(135deg,#12315a,#15243c);display:flex;justify-content:space-between;gap:24px}.muted{color:#a9bad0}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:14px;border-bottom:1px solid #2a405c}th:last-child,td:last-child{text-align:right}.totals{margin:24px 0 0 auto;max-width:360px}.totals div{display:flex;justify-content:space-between;padding:8px}.total{font-size:1.25rem;font-weight:800;border-top:1px solid #49627f}.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:28px}button{border:0;border-radius:12px;padding:13px 20px;font-weight:800;cursor:pointer}.accept{background:#35d59a;color:#03261b}.decline{background:#2b3b51;color:#fff}.notice{padding:16px;border-radius:12px;background:#173c32;color:#aff2d8}@media(max-width:600px){.head{display:block}.table-wrap{overflow:auto}}</style></head><body><main class="wrap"><article class="quote"><header class="head"><div><p class="muted">QUOTE</p><h1><?= e($quote['quote_number']) ?></h1><p><?= e($siteName) ?></p></div><div><strong><?= e($quote['customer_name']) ?></strong><br><span class="muted"><?= e($quote['customer_email']) ?></span><?php if($quote['valid_until']): ?><p>Valid until <?= e($quote['valid_until']) ?></p><?php endif; ?></div></header><div class="body"><?php if($message): ?><p class="notice" role="status"><?= e($message) ?></p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Item</th><th>Qty</th><th>Price</th><th>Total</th></tr></thead><tbody><?php foreach($quote['items'] as $item): ?><tr><td><?= e($item['description']) ?></td><td><?= (int)$item['quantity'] ?></td><td><?= e($quote['currency']) ?> <?= number_format($item['unit_price_minor']/100,2) ?></td><td><?= e($quote['currency']) ?> <?= number_format($item['line_total_minor']/100,2) ?></td></tr><?php endforeach; ?></tbody></table></div><div class="totals"><div><span>Subtotal</span><strong><?= e($quote['currency']) ?> <?= number_format($quote['subtotal_minor']/100,2) ?></strong></div><?php if($quote['discount_minor']): ?><div><span>Discount</span><strong>−<?= e($quote['currency']) ?> <?= number_format($quote['discount_minor']/100,2) ?></strong></div><?php endif; ?><?php if($quote['tax_minor']): ?><div><span>Tax</span><strong><?= e($quote['currency']) ?> <?= number_format($quote['tax_minor']/100,2) ?></strong></div><?php endif; ?><div class="total"><span>Total</span><strong><?= e($quote['currency']) ?> <?= number_format($quote['total_minor']/100,2) ?></strong></div></div><?php if($quote['customer_notes']): ?><h2>Notes</h2><p><?= nl2br(e($quote['customer_notes'])) ?></p><?php endif; ?><form method="post" action="<?= e_attr($basePath) ?>/quote/<?= e_attr($token) ?>" class="actions"><?= $csrf->field() ?><button class="accept" name="decision" value="accept">Accept quote</button><button class="decline" name="decision" value="decline">Decline</button></form><?php endif; ?></div></article></main></body></html>
